UPDATE storage_tbl
SET available_count = available_count - #{count}
WHERE commodity_code = #{commodityCode}
  AND available_count >= #{count}

UPDATE storage_tbl
SET available_count = available_count - #{count},
    frozen_count = frozen_count + #{count}
WHERE commodity_code = #{commodityCode}
  AND available_count >= #{count}

UPDATE storage_tbl
SET frozen_count = frozen_count - #{count}
WHERE commodity_code = #{commodityCode}
  AND frozen_count >= #{count}

UPDATE storage_tbl
SET available_count = available_count + #{count},
    frozen_count = frozen_count - #{count}
WHERE commodity_code = #{commodityCode}
  AND frozen_count >= #{count}

UPDATE storage_tbl
SET available_count = available_count + #{count}
WHERE commodity_code = #{commodityCode}
